function HC:GetCommunityDisplayList()
 local output={};local catalog=self:GetCatalogList();local used={};local i
 for i=1,table.getn(catalog)do local item=catalog[i];local route=self:GetCommunityRoute(item.author,item.id);local copy={};local k,v;for k,v in pairs(item)do copy[k]=v end;copy.route=route;used[item.key]=1;table.insert(output,copy)end
 for i=1,table.getn(self.DB.communityRoutes)do local route=self.DB.communityRoutes[i];local key=self:NameKey(route.author).."~"..route.id;if not used[key]then table.insert(output,{key=key,id=route.id,author=route.author,revision=route.revision,name=route.name,challengeId=route.challengeId,faction=route.faction,className=route.className,minLevel=route.minLevel,maxLevel=route.maxLevel,stepCount=table.getn(route.steps),description=route.description,route=route,downloadedOnly=1})end end
 table.sort(output,function(a,b)if a.challengeId~=b.challengeId then return(a.challengeId or"")<(b.challengeId or"")end;return(a.name or"")<(b.name or"")end);return output
end
