end
function HC:RefreshMyPanel()
 local f=self.Frames.my;local routes=self.DB.routes;local total=table.getn(routes);local max=total-self.ROUTE_ROWS;if max<0 then max=0 end;if self.State.routeOffset>max then self.State.routeOffset=max end;local i
 for i=1,self.ROUTE_ROWS do local route=routes[self.State.routeOffset+i];local row=f.left.rows[i];if route then row.routeId=route.id;row.name:SetText(route.name);row.meta:SetText(self:GetChallengeName(route.challengeId).."  |  "..table.getn(route.steps).." steps");if route.id==self.State.routeId then row:SetBackdropBorderColor(1,.65,.15,1)else row:SetBackdropBorderColor(.25,.22,.17,1)end;row:Show()else row.routeId=nil;row:Hide()end end
 local route=self:GetSelectedRoute();if route and f.loadedRouteId~=route.id then f.loadedRouteId=route.id;f.meta.name:SetText(route.name);f.meta.description:SetText(route.description or"");f.meta.minLevel:SetText(tostring(route.minLevel or 1));f.meta.maxLevel:SetText(tostring(route.maxLevel or 60));local c,ci=self:GetChallenge(route.challengeId);self.State.challengeIndex=ci;f.meta.challenge:SetText(c.name);for i=1,table.getn(self.Factions)do if self.Factions[i]==route.faction then self.State.factionIndex=i end end;for i=1,table.getn(self.Classes)do if self.Classes[i]==route.className then self.State.classIndex=i end end;f.meta.faction:SetText(self.Factions[self.State.factionIndex]);f.meta.class:SetText(self.Classes[self.State.classIndex])end
 if route then local publish=route.publishedRevision and("published r"..route.publishedRevision)or"private";if route.dirty and route.publishedRevision then publish=publish.." / edits not republished"end;f.meta.status:SetText("Revision "..tostring(route.revision or 1).."  |  "..publish);local count=table.getn(route.steps);local stepMax=count-self.STEP_ROWS;if stepMax<0 then stepMax=0 end;if self.State.stepOffset>stepMax then self.State.stepOffset=stepMax end;f.steps.count:SetText(count.." / "..self.MAX_STEPS.." steps");for i=1,self.STEP_ROWS do local index=self.State.stepOffset+i;local step=route.steps[index];local row=f.steps.rows[i];if step then row.stepIndex=index;local coords=step.x and(" "..math.floor(step.x*100)..","..math.floor(step.y*100))or" zone-only";row.text:SetText(index..". "..string.upper(step.type).."  |  "..step.title.."  |  "..step.zone..coords.."  |  mobs L"..tostring(step.minLevel or"?").."-"..tostring(step.maxLevel or"?"));if index==self.State.stepIndex then row:SetBackdropBorderColor(1,.65,.15,1)else row:SetBackdropBorderColor(.25,.22,.17,1)end;row:Show()else row.stepIndex=nil;row:Hide()end end
 else f.meta.status:SetText("Create a route to begin.");f.steps.count:SetText("0 steps");for i=1,self.STEP_ROWS do f.steps.rows[i]:Hide()end end
end
function HC:RefreshCommunityPanel()
 local f=self.Frames.community;f.top.network:SetText(self.DB.settings.networkEnabled and"Network ON"or"Network OFF");f.top.status:SetText(self:NetworkStatus());local list=self:GetCommunityDisplayList();local total=table.getn(list);local max=total-self.COMMUNITY_ROWS;if max<0 then max=0 end;if self.State.communityOffset>max then self.State.communityOffset=max end;f.list.count:SetText(total.." visible route(s)");local i
 for i=1,self.COMMUNITY_ROWS do local item=list[self.State.communityOffset+i];local row=f.list.rows[i];if item then row.communityKey=item.key;local state=item.route and"DOWNLOADED"or(item.downloadedOnly and"SAVED"or"AVAILABLE");row.text:SetText(state.."  |  "..item.name.."  |  "..self:GetChallengeName(item.challengeId).."  |  L"..item.minLevel.."-"..item.maxLevel.."  |  "..item.stepCount.." steps  |  by "..item.author);if item.key==self.State.communityKey then row:SetBackdropBorderColor(1,.65,.15,1)else row:SetBackdropBorderColor(.25,.22,.17,1)end;row:Show()else row.communityKey=nil;row:Hide()end end
 local selected=self:GetSelectedCommunityDisplay();if selected then f.detail.text:SetText(selected.name.." — "..(selected.description or"").."  |  revision "..tostring(selected.revision)..(selected.route and"  |  ready to play"or"  |  metadata only; click Download"))else f.detail.text:SetText("No community route selected. Both publisher and downloader must be online during transfer.")end
end
function HC:RefreshChallengesPanel()
 local f=self.Frames.challenges;local selected=HCChallengerChallenges[self.State.challengeView]or HCChallengerChallenges[1];local i;for i=1,table.getn(f.list.rows)do local row=f.list.rows[i];if i==self.State.challengeView then row:SetBackdropBorderColor(1,.65,.15,1)else row:SetBackdropBorderColor(.25,.22,.17,1)end end;f.detail.icon:SetTexture(selected.icon);f.detail.title:SetText(selected.name);f.detail.rules:SetText(selected.rules);f.detail.advice:SetText(selected.advice)
end
function HC:RefreshUI()
 if not self.DB or not self.Frames.main then return end;local name,button;for name,button in pairs(self.Frames.main.tabs)do if name==self.State.tab then button:LockHighlight()else button:UnlockHighlight()end end;if self.State.tab=="My Routes"then self:RefreshMyPanel()elseif self.State.tab=="Community"then self:RefreshCommunityPanel()else self:RefreshChallengesPanel()end;self:RefreshGuide()
end
function HC:RestoreUISettings()
 if not self.DB then return end;local p=self.DB.settings.position;self.Frames.main:ClearAllPoints();self.Frames.main:SetPoint(p.point or"CENTER",UIParent,p.relPoint or"CENTER",p.x or 0,p.y or 0);local g=self.DB.settings.guidePosition;self.Frames.guide:ClearAllPoints();self.Frames.guide:SetPoint(g.point or"RIGHT",UIParent,g.relPoint or"RIGHT",g.x or-30,g.y or 40);self:SetMinimapAngle(self.DB.settings.minimapAngle);if self.DB.settings.minimap then self.Frames.minimap:Show()else self.Frames.minimap:Hide()end;self:SetTab(self.State.tab)
end
function HC:ShowGuide()self.Frames.guide:Show();self:RefreshGuide()end
function HC:Open()self:RefreshUI();self.Frames.main:Show()end
function HC:Close()self.Frames.main:Hide()end
function HC:Toggle()if self.Frames.main:IsShown()then self:Close()else self:Open()end end

HC:CreateMainFrame();HC:CreateGuideFrame();HC:CreateMinimapButton()
SLASH_HCCHALLENGER1="/hcc";SLASH_HCCHALLENGER2="/hcchallenger"
SlashCmdList["HCCHALLENGER"]=function(message)
 local raw=HC:Trim(message or"",100);local lower=string.lower(raw);if lower=="network on"then HC.DB.settings.networkEnabled=1;HC:JoinNetwork()elseif lower=="network off"then HC.DB.settings.networkEnabled=nil;HC:StopNetwork()elseif lower=="guide"then HC:ShowGuide()elseif lower=="community"then HC:Open();HC:SetTab("Community")elseif lower=="challenges"then HC:Open();HC:SetTab("Challenges")elseif lower=="minimap"then HC.DB.settings.minimap=not HC.DB.settings.minimap;HC:RestoreUISettings()elseif string.sub(lower,1,4)=="new "then HC:CreateRoute(string.sub(raw,5),"STANDARD");HC:Open();HC:SetTab("My Routes")else HC:Toggle()end;if HC.RefreshUI then HC:RefreshUI()end
end
local events=CreateFrame("Frame",nil,UIParent);local names={"VARIABLES_LOADED","PLAYER_ENTERING_WORLD","PLAYER_TARGET_CHANGED","PLAYER_LEVEL_UP","ZONE_CHANGED","ZONE_CHANGED_NEW_AREA","CHAT_MSG_CHANNEL","CHAT_MSG_CHANNEL_NOTICE"};local i;for i=1,table.getn(names)do events:RegisterEvent(names[i])end;events:SetScript("OnEvent",function()HC:OnEvent(event,arg1,arg2,arg9)end);events:SetScript("OnUpdate",function()HC:NetworkUpdate()end)
